for _ in range(200):
    n = rng.choice(candidates_n)
    # choose t so that 1 < t < n-1 and gcd(n,t) > 1
    for __ in range(200):
        t = rng.randint(2, n-2)
        g = math.gcd(n, t)
        if g > 1:
            break
    else:
        continue  # retry n
    # choose a, b positive integers (b >= 1 to keep non-real roots)
    a = rng.randint(1, 9)
    b = rng.randint(1, 9)
