        rx, ry = 1, 0  # result
        bx, by_ = ax, by
        ee = e
        while ee > 0:
            if ee & 1:
                nrx = rx * bx - ry * by_
                nry = rx * by_ + ry * bx
                rx, ry = nrx, nry
            ee >>= 1
            if ee:
                nbx = bx * bx - by_ * by_
                nby = 2 * bx * by_
                bx, by_ = nbx, nby
        return rx, ry
